from __future__ import annotations

from bedrock_models import BedrockRequest
from guardrail_policy import guardrail_audit_payload


def build_audit_event(
    action: str,
    request: BedrockRequest,
    reason: str,
    region: str | None = None,
) -> dict[str, object]:
    event = {
        "action": action,
        "conversation_id": request.conversation_id,
        "idempotency_key": request.idempotency_key,
        "customer_account_id": request.customer_account_id,
        "request_tier": request.request_tier,
        "region": region,
        "reason": reason,
        "retry_attempt": request.retry_attempt,
    }
    if action.startswith("guardrail"):
        event["guardrail"] = guardrail_audit_payload(request)
    return event


def unique_audit_events(results: list[dict[str, object]]) -> list[dict[str, object]]:
    events: list[dict[str, object]] = []
    seen_keys: set[tuple[str, str]] = set()
    for result in results:
        for event in result["audit_events"]:  # type: ignore[index]
            key = (str(event["idempotency_key"]), str(event["action"]))
            if key in seen_keys:
                continue
            seen_keys.add(key)
            events.append(event)
    return events


class AuditLog:
    def __init__(self) -> None:
        self._events: list[dict[str, object]] = []

    def append(self, event: dict[str, object]) -> None:
        self._events.append(event)

    def append_once(self, event: dict[str, object]) -> None:
        key = (event["idempotency_key"], event["action"])
        for existing in self._events:
            if (existing["idempotency_key"], existing["action"]) == key:
                return
        self._events.append(event)

    def all_events(self) -> list[dict[str, object]]:
        return list(self._events)

    def count(self) -> int:
        return len(self._events)

    def by_action(self, action: str) -> list[dict[str, object]]:
        return [event for event in self._events if event["action"] == action]

