from __future__ import annotations

from audit_log import build_audit_event
from bedrock_models import BedrockRequest, ModelProfile, RegionQuota, effective_tpm_required, validate_model_request
from billing_ledger import build_billing_event
from decision_store import decision_store_from
from gateway_summary import build_gateway_summary
from guardrail_policy import guardrail_reason, request_is_blocked
from quota_policy import choose_region, routing_snapshot


def _quota_result(region: RegionQuota, request: BedrockRequest, model: ModelProfile) -> dict[str, object]:
    return {
        "region": region.region,
        "reserved_rpm": 1,
        "reserved_tpm": effective_tpm_required(request, model),
        "streaming": request.streaming,
        "time_to_first_token_ms": region.time_to_first_token_ms,
        "effective_tpm_required": effective_tpm_required(request, model),
    }


def _blocked_result(request: BedrockRequest) -> dict[str, object]:
    return {
        "status": "blocked",
        "region": None,
        "quota": None,
        "rejection_reason": "guardrail_blocked",
        "audit_events": [
            build_audit_event("guardrail_blocked", request, guardrail_reason(request))
        ],
        "billing_events": [],
        "route_diagnostics": None,
    }


def _rejected_result(
    request: BedrockRequest,
    model: ModelProfile,
    regions: list[RegionQuota],
    primary_region: str,
) -> dict[str, object]:
    return {
        "status": "rejected",
        "region": None,
        "quota": None,
        "rejection_reason": "no_region_quota",
        "audit_events": [build_audit_event("route_rejected", request, "no_region_quota")],
        "billing_events": [],
        "route_diagnostics": routing_snapshot(regions, request, model, primary_region),
    }


def _routed_result(
    request: BedrockRequest,
    model: ModelProfile,
    chosen: RegionQuota,
    regions: list[RegionQuota],
    primary_region: str,
) -> dict[str, object]:
    quota = _quota_result(chosen, request, model)
    return {
        "status": "routed",
        "region": chosen.region,
        "quota": quota,
        "rejection_reason": None,
        "audit_events": [build_audit_event("route_selected", request, "quota_reserved", chosen.region)],
        "billing_events": [build_billing_event(request, quota)],
        "route_diagnostics": routing_snapshot(regions, request, model, primary_region),
    }


def route_bedrock_request(
    request: BedrockRequest,
    model: ModelProfile,
    regions: list[RegionQuota],
    primary_region: str,
    prior_decisions: dict[str, dict[str, object]] | None = None,
) -> dict[str, object]:
    validate_model_request(request, model)
    decisions = decision_store_from(prior_decisions)
    existing = decisions.get(request.idempotency_key)
    if existing is not None:
        return existing

    if request_is_blocked(request):
        return decisions.save(request.idempotency_key, _blocked_result(request))

    chosen = choose_region(regions, request, model, primary_region)
    if chosen is None:
        return decisions.save(request.idempotency_key, _rejected_result(request, model, regions, primary_region))

    return decisions.save(request.idempotency_key, _routed_result(request, model, chosen, regions, primary_region))


def summarize_gateway_run(results: list[dict[str, object]]) -> dict[str, object]:
    return build_gateway_summary(results)


class BedrockInferenceGateway:
    def __init__(self, model: ModelProfile, regions: list[RegionQuota], primary_region: str) -> None:
        self.model = model
        self.regions = list(regions)
        self.primary_region = primary_region
        self._decisions: dict[str, dict[str, object]] = {}

    def route(self, request: BedrockRequest) -> dict[str, object]:
        return route_bedrock_request(
            request,
            self.model,
            self.regions,
            self.primary_region,
            self._decisions,
        )

    def summarize(self) -> dict[str, object]:
        return summarize_gateway_run(list(self._decisions.values()))

    def decision_count(self) -> int:
        return len(self._decisions)

    def routed_regions(self) -> tuple[str, ...]:
        regions: list[str] = []
        for decision in self._decisions.values():
            region = decision.get("region")
            if region is not None:
                regions.append(str(region))
        return tuple(regions)

