from __future__ import annotations

from dataclasses import dataclass


VALID_GUARDRAIL_DECISIONS = {"allow", "block"}
VALID_REQUEST_TIERS = {"standard", "priority", "enterprise"}
VALID_REGION_STATES = {"healthy", "degraded", "draining"}


def _require_text(value: str, field_name: str) -> None:
    if not value.strip():
        raise ValueError(f"{field_name} required")


@dataclass(frozen=True)
class ModelProfile:
    model_id: str
    output_token_burndown: int
    family: str = "anthropic"
    max_input_tokens: int = 200_000
    max_output_tokens: int = 8_192
    supports_streaming: bool = True

    def __post_init__(self) -> None:
        _require_text(self.model_id, "model_id")
        _require_text(self.family, "family")
        if self.output_token_burndown <= 0:
            raise ValueError("output_token_burndown must be positive")
        if self.max_input_tokens <= 0:
            raise ValueError("max_input_tokens must be positive")
        if self.max_output_tokens <= 0:
            raise ValueError("max_output_tokens must be positive")


@dataclass(frozen=True)
class RegionQuota:
    region: str
    remaining_rpm: int
    remaining_tpm: int
    time_to_first_token_ms: int
    fallback_enabled: bool = True
    health_state: str = "healthy"
    concurrent_streams: int = 0
    max_concurrent_streams: int = 100

    def __post_init__(self) -> None:
        _require_text(self.region, "region")
        if self.remaining_rpm < 0:
            raise ValueError("remaining_rpm must be non-negative")
        if self.remaining_tpm < 0:
            raise ValueError("remaining_tpm must be non-negative")
        if self.time_to_first_token_ms < 0:
            raise ValueError("time_to_first_token_ms must be non-negative")
        if self.health_state not in VALID_REGION_STATES:
            raise ValueError("unsupported health_state")
        if self.concurrent_streams < 0:
            raise ValueError("concurrent_streams must be non-negative")
        if self.max_concurrent_streams <= 0:
            raise ValueError("max_concurrent_streams must be positive")


@dataclass(frozen=True)
class GuardrailTrace:
    guardrail_id: str
    version: str
    decision: str
    reason: str
    blocked_categories: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        _require_text(self.guardrail_id, "guardrail_id")
        _require_text(self.version, "version")
        if self.decision not in VALID_GUARDRAIL_DECISIONS:
            raise ValueError("decision must be allow or block")
        _require_text(self.reason, "reason")
        for category in self.blocked_categories:
            _require_text(category, "blocked category")


@dataclass(frozen=True)
class StreamingProfile:
    first_token_slo_ms: int
    client_timeout_ms: int
    retry_budget: int
    stream_required: bool = True

    def __post_init__(self) -> None:
        if self.first_token_slo_ms <= 0:
            raise ValueError("first_token_slo_ms must be positive")
        if self.client_timeout_ms <= 0:
            raise ValueError("client_timeout_ms must be positive")
        if self.retry_budget < 0:
            raise ValueError("retry_budget must be non-negative")
        if self.client_timeout_ms < self.first_token_slo_ms:
            raise ValueError("client timeout must be at least first token SLO")


@dataclass(frozen=True)
class BedrockRequest:
    conversation_id: str
    idempotency_key: str
    input_tokens: int
    requested_output_tokens: int
    streaming: bool
    guardrail_decision: str = "allow"
    customer_account_id: str = "unknown-account"
    request_tier: str = "standard"
    retry_attempt: int = 0
    guardrail_trace: GuardrailTrace | None = None

    def __post_init__(self) -> None:
        _require_text(self.conversation_id, "conversation_id")
        _require_text(self.idempotency_key, "idempotency_key")
        if self.input_tokens < 0:
            raise ValueError("input_tokens must be non-negative")
        if self.requested_output_tokens < 0:
            raise ValueError("requested_output_tokens must be non-negative")
        if self.guardrail_decision not in VALID_GUARDRAIL_DECISIONS:
            raise ValueError("guardrail_decision must be allow or block")
        _require_text(self.customer_account_id, "customer_account_id")
        if self.request_tier not in VALID_REQUEST_TIERS:
            raise ValueError("unsupported request_tier")
        if self.retry_attempt < 0:
            raise ValueError("retry_attempt must be non-negative")
        if self.guardrail_trace is not None and self.guardrail_trace.decision != self.guardrail_decision:
            raise ValueError("guardrail_trace decision mismatch")


@dataclass(frozen=True)
class QuotaReservation:
    region: str
    reserved_rpm: int
    reserved_tpm: int
    streaming: bool
    time_to_first_token_ms: int
    effective_tpm_required: int

    def __post_init__(self) -> None:
        _require_text(self.region, "region")
        if self.reserved_rpm <= 0:
            raise ValueError("reserved_rpm must be positive")
        if self.reserved_tpm < 0:
            raise ValueError("reserved_tpm must be non-negative")
        if self.time_to_first_token_ms < 0:
            raise ValueError("time_to_first_token_ms must be non-negative")
        if self.effective_tpm_required < 0:
            raise ValueError("effective_tpm_required must be non-negative")


@dataclass(frozen=True)
class RouteDecision:
    status: str
    region: str | None
    rejection_reason: str | None
    quota: QuotaReservation | None
    route_reason: str

    def __post_init__(self) -> None:
        if self.status not in {"routed", "blocked", "rejected"}:
            raise ValueError("unsupported route status")
        if self.status == "routed" and self.region is None:
            raise ValueError("routed decision requires region")
        if self.status != "routed" and self.rejection_reason is None:
            raise ValueError("terminal non-routed decision requires rejection reason")
        _require_text(self.route_reason, "route_reason")


def effective_tpm_required(request: BedrockRequest, model: ModelProfile) -> int:
    return request.input_tokens + request.requested_output_tokens * model.output_token_burndown


def validate_model_request(request: BedrockRequest, model: ModelProfile) -> None:
    if request.input_tokens > model.max_input_tokens:
        raise ValueError("input token request exceeds model limit")
    if request.requested_output_tokens > model.max_output_tokens:
        raise ValueError("output token request exceeds model limit")
    if request.streaming and not model.supports_streaming:
        raise ValueError("model does not support streaming")


def default_streaming_profile() -> StreamingProfile:
    return StreamingProfile(
        first_token_slo_ms=1_500,
        client_timeout_ms=30_000,
        retry_budget=2,
        stream_required=True,
    )

