        if self.status not in {"routed", "blocked", "rejected"}:
            raise ValueError("unsupported route status")
        if self.status == "routed" and self.region is None:
            raise ValueError("routed decision requires region")
        if self.status != "routed" and self.rejection_reason is None:
            raise ValueError("terminal non-routed decision requires rejection reason")
        _require_text(self.route_reason, "route_reason")


def effective_tpm_required(request: BedrockRequest, model: ModelProfile) -> int:
    return request.input_tokens + request.requested_output_tokens * model.output_token_burndown


def validate_model_request(request: BedrockRequest, model: ModelProfile) -> None:
    if request.input_tokens > model.max_input_tokens:
        raise ValueError("input token request exceeds model limit")
    if request.requested_output_tokens > model.max_output_tokens:
        raise ValueError("output token request exceeds model limit")
    if request.streaming and not model.supports_streaming:
        raise ValueError("model does not support streaming")


def default_streaming_profile() -> StreamingProfile:
    return StreamingProfile(
        first_token_slo_ms=1_500,
        client_timeout_ms=30_000,
        retry_budget=2,
        stream_required=True,
    )

