class DecisionStore:
    def __init__(self, seed: dict[str, dict[str, object]] | None = None) -> None:
        self._by_idempotency_key: dict[str, dict[str, object]] = seed if seed is not None else {}

    def get(self, idempotency_key: str) -> dict[str, object] | None:
        return self._by_idempotency_key.get(idempotency_key)

    def save(self, idempotency_key: str, decision: dict[str, object]) -> dict[str, object]:
        self._by_idempotency_key[idempotency_key] = decision
        return decision

    def save_once(self, idempotency_key: str, decision: dict[str, object]) -> dict[str, object]:
        existing = self.get(idempotency_key)
        if existing is not None:
            return existing
        self._by_idempotency_key[idempotency_key] = decision
        return decision

    def all_decisions(self) -> list[dict[str, object]]:
        return list(self._by_idempotency_key.values())

    def count(self) -> int:
        return len(self._by_idempotency_key)

    def keys(self) -> list[str]:
        return sorted(self._by_idempotency_key)

    def status_counts(self) -> dict[str, int]:
        counts = {"routed": 0, "blocked": 0, "rejected": 0}
        for decision in self._by_idempotency_key.values():
            status = str(decision["status"])
            if status in counts:
                counts[status] += 1
        return counts

    def snapshot(self) -> dict[str, object]:
        counts = self.status_counts()
        return {
            "decision_count": self.count(),
            "idempotency_keys": self.keys(),
            "routed_count": counts["routed"],
            "blocked_count": counts["blocked"],
            "rejected_count": counts["rejected"],
        }

    def decisions_by_status(self, status: str) -> list[dict[str, object]]:
        return [
            decision
            for decision in self._by_idempotency_key.values()
            if decision["status"] == status
        ]

    def routed_regions(self) -> tuple[str, ...]:
        regions: list[str] = []
        for decision in self.decisions_by_status("routed"):
            region = decision.get("region")
            if region is not None:
                regions.append(str(region))
        return tuple(regions)

    def clear(self) -> None:
        self._by_idempotency_key.clear()


def decision_store_from(prior_decisions: dict[str, dict[str, object]] | None) -> DecisionStore:
    return DecisionStore(prior_decisions)

