from __future__ import annotations

from bedrock_models import BedrockRequest, ModelProfile, RegionQuota, effective_tpm_required


def region_accepts_stream(region: RegionQuota, request: BedrockRequest) -> bool:
    if not request.streaming:
        return True
    return region.concurrent_streams < region.max_concurrent_streams


def region_is_available(region: RegionQuota, allow_degraded: bool = True) -> bool:
    if region.health_state == "healthy":
        return True
    if region.health_state == "degraded":
        return allow_degraded
    return False


def rpm_available(region: RegionQuota) -> bool:
    return region.remaining_rpm >= 1


def tpm_available(region: RegionQuota, request: BedrockRequest, model: ModelProfile) -> bool:
    return region.remaining_tpm >= effective_tpm_required(request, model)


def can_reserve_quota(
    region: RegionQuota,
    request: BedrockRequest,
    model: ModelProfile,
    allow_degraded: bool = True,
) -> bool:
    if not region_is_available(region, allow_degraded):
        return False
    if not region_accepts_stream(region, request):
        return False
    return rpm_available(region)


def quota_shortfalls(region: RegionQuota, request: BedrockRequest, model: ModelProfile) -> list[str]:
    shortfalls: list[str] = []
    if not rpm_available(region):
        shortfalls.append("rpm")
    if not tpm_available(region, request, model):
        shortfalls.append("tpm")
    if not region_accepts_stream(region, request):
        shortfalls.append("streams")
    if not region_is_available(region):
        shortfalls.append("health")
    return shortfalls


def primary_region(regions: list[RegionQuota], primary_region_name: str) -> RegionQuota | None:
    for region in regions:
        if region.region == primary_region_name:
            return region
    return None


def fallback_regions(regions: list[RegionQuota], primary_region_name: str) -> list[RegionQuota]:
    fallbacks: list[RegionQuota] = []
    for region in regions:
        if region.region == primary_region_name:
            continue
        if not region.fallback_enabled:
            continue
        fallbacks.append(region)
    return fallbacks


def eligible_regions(
    regions: list[RegionQuota],
    request: BedrockRequest,
    model: ModelProfile,
    primary_region_name: str,
) -> list[RegionQuota]:
    candidates: list[RegionQuota] = []
    primary = primary_region(regions, primary_region_name)
    if primary is not None:
        candidates.append(primary)
    candidates.extend(fallback_regions(regions, primary_region_name))
    return [region for region in candidates if can_reserve_quota(region, request, model)]


def choose_region(
    regions: list[RegionQuota],
    request: BedrockRequest,
    model: ModelProfile,
    primary_region_name: str,
) -> RegionQuota | None:
    primary = primary_region(regions, primary_region_name)
    if primary is not None and can_reserve_quota(primary, request, model):
        return primary

    fallbacks = fallback_regions(regions, primary_region_name)
    eligible = [region for region in fallbacks if can_reserve_quota(region, request, model)]
    if not eligible:
        return None
    return sorted(eligible, key=lambda region: region.time_to_first_token_ms)[0]


def capacity_snapshot(region: RegionQuota, request: BedrockRequest, model: ModelProfile) -> dict[str, object]:
    required_tpm = effective_tpm_required(request, model)
    return {
        "region": region.region,
        "remaining_rpm": region.remaining_rpm,
        "remaining_tpm": region.remaining_tpm,
        "required_rpm": 1,
        "required_tpm": required_tpm,
        "rpm_ok": rpm_available(region),
        "tpm_ok": tpm_available(region, request, model),
        "stream_ok": region_accepts_stream(region, request),
        "health_state": region.health_state,
        "shortfalls": quota_shortfalls(region, request, model),
    }


def routing_snapshot(
    regions: list[RegionQuota],
    request: BedrockRequest,
    model: ModelProfile,
    primary_region_name: str,
) -> dict[str, object]:
    return {
        "primary_region": primary_region_name,
        "effective_tpm_required": effective_tpm_required(request, model),
        "regions": [capacity_snapshot(region, request, model) for region in regions],
        "eligible_region_names": [
            region.region for region in eligible_regions(regions, request, model, primary_region_name)
        ],
    }


class QuotaPlanner:
    def __init__(self, model: ModelProfile, regions: list[RegionQuota], primary_region_name: str) -> None:
        self.model = model
        self.regions = list(regions)
        self.primary_region_name = primary_region_name

    def choose(self, request: BedrockRequest) -> RegionQuota | None:
        return choose_region(self.regions, request, self.model, self.primary_region_name)

    def snapshot(self, request: BedrockRequest) -> dict[str, object]:
        return routing_snapshot(self.regions, request, self.model, self.primary_region_name)

    def shortfalls(self, request: BedrockRequest) -> dict[str, list[str]]:
        return {
            region.region: quota_shortfalls(region, request, self.model)
            for region in self.regions
        }

